func decomposeCall(ctx *planner.Context, call atom.Atom, requireTopLevel bool) (atom.Atom, planner.DecompositionStatus) {
	empty := atom.EmptyList()
	if ctx == nil || ctx.Execution == nil || ctx.Prepared == nil {
		return empty, planner.InvalidContext
	}
	ex := ctx.Execution
	ex.ResetDiagnostics()
	if ctx.WorldState == nil || ctx.Bindings == nil {
		return empty, planner.InvalidContext
	}
	if !call.Is(atom.KindList) || call.Len() < 1 {
		return empty, planner.InvalidCall
	}
	head, _ := call.At(0)
	if !head.Is(atom.KindSymbol) {
		return empty, planner.InvalidCall
	}
	argumentCount := call.Len() - 1
	_ = argumentCount
	ex.Begin(ctx, factSymbols, callNames)
	entry := -1
	if entry < 0 && head.Symbol() == sym6 && argumentCount == 0 {
		entry = 1
	}
	if entry < 0 {
		return empty, planner.InvalidCall
	}
	ex.DebugBeginPlan(&definition, uint32(entry))
	result := 0
	switch entry {
	case 1:
		result = ex.Run(method1)
	}
	if result == 0 {
		ex.DebugEndPlan(&definition, false)
		return empty, ex.FailureState
	}
	for ex.PendingCount() != 0 {
		next := ex.PopPending()
		if next == nil {
			break
		}
		if ex.Run(next) == 0 {
			ex.DebugEndPlan(&definition, false)
			return empty, ex.FailureState
		}
	}
	ex.DebugEndPlan(&definition, true)
	return ex.PlanAtom(), planner.Succeeded
}
